S = "Hakeem Force Academy"
QS = [
 (S, "Change into indirect speech: She told, \"It is a very cold day.\"", ["She told that it is a very cold day.", "She told that it was a very cold day.", "She told that it had been a very cold day.", "She told that it will be a very cold day."], 1,
  "The reporting verb is in the past tense, so the present tense \"is\" changes to the past tense \"was\". The quotation marks are removed and \"that\" is added.", "In indirect speech, \"today\" changes to \"that day\" and \"now\" changes to \"then\".", [368]),
 (S, "What is the meaning of the idiom \"to take to one's heels\"?", ["To walk slowly", "To run away", "To kneel down", "To fight bravely"], 1,
  "The idiom \"take to one's heels\" means to run away quickly, usually from danger.", "A similar idiom is \"to show a clean pair of heels\", which means to outrun someone.", [3023]),
 (S, "What is a synonym of the word \"total\"?", ["Part", "Sum", "Few", "Remainder"], 1,
  "\"Total\" means the whole amount after adding everything together, which is the same as \"sum\".", "The opposite of total in this sense is \"part\" or \"fraction\".", [3163]),
 (S, "What is the length of a marathon race in miles?", ["24.2 miles", "26.2 miles", "28.5 miles", "30 miles"], 1,
  "A standard marathon is 42.195 km. Dividing by 1.609 gives about 26.2 miles.", "The marathon distance of 42.195 km was fixed by World Athletics after the 1908 London Olympics.", [2970]),
 (S, "Complete the sentence: Our team ______ their track suits.", ["is wearing", "are wearing", "were wearing", "have wearing"], 0,
  "\"Team\" is treated here as one unit, so the singular verb \"is wearing\" is used.", "In British English a collective noun like team can also take a plural verb, but the singular is the textbook answer.", [1527]),
 (S, "If A transpose is equal to A, then the matrix A is called what?", ["Skew symmetric", "Symmetric", "Orthogonal", "Identity"], 1,
  "A square matrix with A^T = A is called a symmetric matrix. If A^T = -A, it is skew symmetric.", "The diagonal entries of a skew symmetric matrix are always zero.", [1871]),
 (S, "A car travels 70 km in one hour. How much distance will it travel in 40 minutes at the same speed?", ["40 km", "42 km", "46.67 km", "50 km"], 2,
  "40 minutes is 40/60 = 2/3 of an hour. Distance = 70 x 2/3 = 46.67 km.", "Distance equals speed multiplied by time.", [1315]),
 (S, "A train's speed is double that of a car. If the car travels 60 km in 1 hour, how much distance will the train cover in 30 minutes?", ["30 km", "45 km", "90 km", "60 km"], 3,
  "The car speed is 60 km per hour, so the train speed is 120 km per hour. In 30 minutes (half an hour) the train covers 120 x 1/2 = 60 km.", "In the same 30 minutes the car covers 30 km.", [104]),
 (S, "Insulin is used for the treatment of which disease?", ["Diabetes", "Malaria", "Typhoid", "Asthma"], 0,
  "Insulin is a hormone that controls blood sugar, so it is used to treat diabetes.", "Insulin is produced by the beta cells of the pancreas.", [2222]),
 (S, "Who was the scribe (writer) of the Treaty of Hudaibiyah?", ["Hazrat Abu Bakr (RA)", "Hazrat Umar (RA)", "Hazrat Ali (RA)", "Hazrat Uthman (RA)"], 2,
  "Hazrat Ali (RA) wrote the text of the Treaty of Hudaibiyah as dictated by the Holy Prophet (PBUH).", "Suhail bin Amr represented the Quraish in the treaty.", [4289]),
 (S, "The Battle of the Trench (Khandaq) is connected with which Surah of the Holy Quran?", ["Surah Al-Anfal", "Surah Al-Ahzab", "Surah Aal-e-Imran", "Surah At-Tawbah"], 1,
  "The events of the Battle of the Trench (also called Ahzab, the Confederates) are described in Surah Al-Ahzab.", "The battle was fought in 5 AH.", [2411]),
 (S, "What is a right angled triangle?", ["A triangle with all angles less than 90 degrees", "A triangle with one angle of 90 degrees", "A triangle with one angle more than 90 degrees", "A triangle with all sides equal"], 1,
  "A right angled triangle has exactly one angle equal to 90 degrees.", "The side opposite the right angle is called the hypotenuse.", [904]),
 (S, "In an upper triangular matrix, what are the entries below the main diagonal?", ["All 1", "All 0", "All equal to the diagonal entries", "All negative"], 1,
  "A matrix is upper triangular when every entry below the main diagonal is zero, and the nonzero entries lie on or above the diagonal.", "In a lower triangular matrix the entries above the diagonal are zero.", [1945, 1946]),
 (S, "The Battle of Badr, the first battle of Islam, was fought between the Muslims and which tribe?", ["Banu Quraizah", "Quraish of Makkah", "Banu Nadir", "Banu Ghatafan"], 1,
  "The Battle of Badr in 2 AH was fought between the Muslims of Madina and the Quraish of Makkah.", "The Muslims had about 313 men against about 1000 of the Quraish.", [1376, 2410]),
 (S, "Who was the first Pakistani to score a triple century in Test cricket?", ["Inzamam-ul-Haq", "Hanif Mohammad", "Javed Miandad", "Younis Khan"], 1,
  "Hanif Mohammad scored 337 against the West Indies at Bridgetown in 1958, the first Pakistani triple century.", "Younis Khan later scored 313 against Sri Lanka in 2009, and Hanif's 337 was the Pakistan record until Inzamam, Younis and others fell short of it.", [1245]),
 (S, "What is the antonym of \"trivial\"?", ["Petty", "Minor", "Important", "Small"], 2,
  "\"Trivial\" means of little importance, so its opposite is \"important\" or significant.", "Synonyms of trivial include petty, minor and insignificant.", [465]),
 (S, "What is the synonym (closest meaning) of \"trivial\"?", ["Serious", "Insignificant", "Valuable", "Huge"], 1,
  "\"Trivial\" means of very little value or importance, which is the same as insignificant.", "The noun form is \"trivia\", meaning unimportant details.", [2821, 3202]),
 (S, "What is the synonym of \"troubled\"?", ["Calm", "Worried", "Happy", "Relaxed"], 1,
  "\"Troubled\" means disturbed or anxious, which is close to worried or distressed.", "The opposite of troubled is calm or peaceful.", [2822, 527]),
 (S, "What is the synonym of the word \"trouble\"?", ["Ease", "Difficulty", "Comfort", "Peace"], 1,
  "\"Trouble\" means a problem or hardship, which is the same as difficulty.", "Other synonyms include distress and worry.", [3203]),
 (S, "If the 3rd day of a month is Tuesday, what day will the 26th be?", ["Wednesday", "Thursday", "Friday", "Tuesday"], 1,
  "From the 3rd to the 26th is 23 days. 23 divided by 7 leaves 2, so Tuesday + 2 = Thursday.", "The 10th, 17th and 24th of this month are also Tuesdays.", [1900]),
 (S, "If the 1st day of a month is Tuesday, what day will the 21st be?", ["Monday", "Tuesday", "Sunday", "Wednesday"], 0,
  "From the 1st to the 21st is 20 days. 20 divided by 7 leaves 6, so Tuesday + 6 = Monday.", "The 22nd is exactly 3 weeks after the 1st, so it is a Tuesday.", [1901]),
 (S, "How many degrees does a circle make in one complete turn?", ["180", "270", "90", "360"], 3,
  "One complete rotation around a point is 360 degrees.", "A half turn is 180 degrees and a quarter turn is 90 degrees.", [1706]),
 (S, "What type of number is 7?", ["Irrational number", "Rational number", "Imaginary number", "Negative number"], 1,
  "7 can be written as 7/1, a ratio of two integers, so it is a rational number.", "7 is also a prime number, a natural number and an odd number.", [1053]),
 (S, "How many Muslims took part in the Battle of Uhud at the start?", ["313", "1000", "700", "3000"], 2,
  "About 700 Muslims marched to Uhud with the Holy Prophet (PBUH), after about 300 hypocrites led by Abdullah bin Ubayy returned.", "The Quraish army had about 3000 men under Abu Sufyan.", [1754, 1756]),
 (S, "What does the name Uhud mean?", ["Standing alone (solitary)", "Full moon", "Fortress", "Victory"], 0,
  "Uhud means standing alone, as the mountain stands separate from the other hills near Madina.", "The Battle of Uhud was fought near this mountain in 3 AH.", [3025, 3026]),
 (S, "Who was the leader of the Muslim army in the Battle of Uhud?", ["Hazrat Hamza (RA)", "Hazrat Khalid bin Walid (RA)", "The Holy Prophet Muhammad (PBUH)", "Hazrat Abu Bakr (RA)"], 2,
  "The Holy Prophet Muhammad (PBUH) himself commanded the Muslim army at Uhud.", "He placed 50 archers on the Ainain hill under Abdullah bin Jubair.", [4396]),
 (S, "To which clan of the Quraish did Hazrat Umar (RA) belong?", ["Banu Adi", "Banu Hashim", "Banu Umayya", "Banu Taym"], 0,
  "Hazrat Umar bin Khattab (RA) belonged to Banu Adi, a clan of the Quraish.", "Hazrat Abu Bakr (RA) belonged to Banu Taym.", [3245]),
 (S, "Umm-ul-Masakeen (Mother of the Poor) is the title of which wife of the Holy Prophet (PBUH)?", ["Hazrat Khadija (RA)", "Hazrat Aisha (RA)", "Hazrat Zainab bint Khuzaymah (RA)", "Hazrat Hafsa (RA)"], 2,
  "Hazrat Zainab bint Khuzaymah (RA) was known as Umm-ul-Masakeen because of her great generosity to the poor.", "She died within a few months of marrying the Prophet (PBUH) and is among the wives who passed away in his lifetime, along with Hazrat Khadija (RA).", [2476]),
 (S, "Bani Israel (the Ummah of Israel) belonged to which prophet?", ["Hazrat Ibrahim (AS)", "Hazrat Musa (AS)", "Hazrat Nuh (AS)", "Hazrat Salih (AS)"], 1,
  "Bani Israel were the people to whom Hazrat Musa (AS) was sent, and he led them out of Egypt.", "Israel was the title of Hazrat Yaqub (AS), the ancestor of Bani Israel.", [1448, 2441]),
 (S, "A man is walking towards the north. If he turns left and walks, which direction is he facing?", ["East", "West", "South", "North"], 1,
  "Facing north, the left hand points to the west, so he now faces west.", "Facing north, a right turn leads to the east.", [1862]),
]
